import {jest} from '@jest/globals';
import {ToolRegistry, type ToolExecutor} from './registry.js';

function registerWeather(registry: ToolRegistry, execute: ToolExecutor): void {
  registry.register(
    {
      name: 'weather',
      description: 'Get weather',
      inputSchema: {
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      },
    },
    execute
  );
}

describe('ToolRegistry', () => {
  it('rejects an invalid static schema when the tool is registered', () => {
    const registry = new ToolRegistry();
    const invalidSchema = {
      type: 'object',
      properties: {location: {type: 'not-a-json-schema-type'}},
    };

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Has an invalid JSON Schema type',
          inputSchema: invalidSchema,
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_weather/);
  });

  it('returns a required-property rejection without invoking the executor', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'sunny');
    registerWeather(registry, execute);

    const response = await registry.execute('weather', {});

    expect({response, executorCalls: execute.mock.calls}).toEqual({
      response: {result: '/location is required'},
      executorCalls: [],
    });
  });

  it('validates each execution against the current function-valued schema', async () => {
    const registry = new ToolRegistry();
    const stringSchema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const numberSchema = {
      type: 'object',
      properties: {location: {type: 'number'}},
      required: ['location'],
    };
    let currentSchema = stringSchema;
    const execute = jest.fn(async () => 'sunny');
    registry.register(() => ({name: 'weather', description: 'Get weather', inputSchema: currentSchema}), execute);

    const firstResponse = await registry.execute('weather', {location: 42});
    currentSchema = numberSchema;
    const secondResponse = await registry.execute('weather', {location: 42});
    const executorCalls = execute.mock.calls;

    expect({
      firstRejectedAsString: /location must be string/.test(firstResponse.result),
      secondResponse,
      executorCallCount: executorCalls.length,
    }).toEqual({
      firstRejectedAsString: true,
      secondResponse: {result: 'sunny'},
      executorCallCount: 1,
    });
  });

  it('passes valid input with an extra property to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'sunny');
    const input = {location: 'Berlin', requestId: 'forecast-1'};
    registerWeather(registry, execute);

    const response = await registry.execute('weather', input);

    expect({response, executorCalls: execute.mock.calls}).toEqual({
      response: {result: 'sunny'},
      executorCalls: [[input, undefined]],
    });
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L22), [validated by: returns a required-property rejection without invoking the executor](../../src/orchestration/tools/registry.test.ts#L39)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L52)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by: passes valid input with an extra property to the executor unchanged](../../src/orchestration/tools/registry.test.ts#L83)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L100), [validated by: rejects an invalid static schema when the tool is registered](../../src/orchestration/tools/registry.test.ts#L20)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema`.
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: validates each execution against the current function-valued schema](../../src/orchestration/tools/registry.test.ts#L52)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L118)).
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';
import Ajv, {type ValidateFunction} from 'ajv';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

interface ValidationError {
  instancePath?: string;
  dataPath?: string;
  keyword: string;
  params: Record<string, unknown>;
}

function describeValidationErrors(validator: ValidateFunction): string {
  const errors = validator.errors as unknown as ValidationError[] | null | undefined;
  const descriptions = errors?.map(describeValidationError);
  return descriptions?.join('; ') ?? 'input failed validation';
}

function describeValidationError(error: ValidationError): string {
  const path = error.instancePath || error.dataPath || '/';
  if (error.keyword === 'required') {
    return `${path}${path === '/' ? '' : '/'}${String(error.params.missingProperty)} is required`;
  }
  if (error.keyword === 'type') {
    return `${path} must be ${String(error.params.type)}`;
  }
  return `${path} failed ${error.keyword}`;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({
    strict: false,
    validateFormats: false,
  } as unknown as ConstructorParameters<typeof Ajv>[0]);
  private readonly validators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private validatorFor(tool: StoredTool, definition: ToolDefinition): ValidateFunction {
    if (tool.validator) return tool.validator;
    const cached = this.validators.get(definition.inputSchema);
    if (cached) return cached;
    const validator = this.ajv.compile(definition.inputSchema);
    this.validators.set(definition.inputSchema, validator);
    return validator;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validator = this.ajv.compile(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Invalid input schema for tool ${resolved.name}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Executes a registered tool under the input contract in specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = this.validatorFor(tool, definition);
    if (!validator(input)) {
      const result = describeValidationErrors(validator);
      log.info('tool', 'input rejected', {name, validationErrors: result});
      return {result};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
